8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.rest.function.owner.OwnerRegion;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName",
23	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials",
25	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "locality",
27	        expression = "java(deriveLocality(owner))")
28	    @Mapping(target = "timezone",
29	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerTimezone.fromRegion(deriveLocality(owner)))")
30	    @Mapping(target = "contactPreference",
31	        expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
32	    @Mapping(target = "identityKey",
33	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId()))")
34	    @Mapping(target = "checkDigit",
35	        expression = "java(luhnCheckDigit(owner.getCustomerCode()))")
36	    @Mapping(target = "ageBand",
37	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()))")
38	    @Mapping(target = "telephoneDisplay",
39	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneDisplay.of(owner.getTelephone()))")
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    Owner toOwner(OwnerDto ownerDto);
43	
44	    @Mapping(target = "id", ignore = true)
45	    @Mapping(target = "pets", ignore = true)
46	    Owner toOwner(OwnerFieldsDto ownerDto);
47	
48	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
49	
50	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
51	
52	    /**
53	     * Derives the owner's locality (region) from the region-and-hash identity: the {@code <REGION>}
54	     * segment of the {@code <REGION>-<HASH8>} {@code customerCode}. The region embedded in the code
55	     * is itself derived (postcode preferred, then city) when the owner is created, so a postcode in a
56	     * known range still wins over the city. When no such code is present (e.g. legacy owners), falls
57	     * back to deriving the region live from the postcode/city via {@link OwnerRegion}.
58	     */
59	    default String deriveLocality(Owner owner) {
60	        String code = owner.getCustomerCode();
61	        if (code != null) {
62	            int dash = code.indexOf('-');
63	            if (dash > 0) {
64	                return code.substring(0, dash);
65	            }
66	        }
67	        return OwnerRegion.fromPostcodeOrCity(owner.getPostcode(), owner.getCity());
68	    }
69	
70	    /**
71	     * Computes the single Luhn check digit (0-9) over the digits contained in the given
72	     * customerCode. Non-digit characters (the separators) are ignored; from the rightmost digit
73	     * leftwards every second digit is doubled (subtracting 9 when the result exceeds 9), and the
74	     * check digit is {@code (10 - (sum % 10)) % 10}. Returns 0 when the code is null.
75	     */
76	    default int luhnCheckDigit(String customerCode) {
77	        if (customerCode == null) {
78	            return 0;
79	        }
80	        int sum = 0;
81	        boolean dbl = true;
82	        for (int i = customerCode.length() - 1; i >= 0; i--) {
83	            char c = customerCode.charAt(i);
84	            if (c < '0' || c > '9') {
85	                continue;
86	            }
87	            int d = c - '0';
88	            if (dbl) {
89	                d *= 2;
90	                if (d > 9) {
91	                    d -= 9;
92	                }
93	            }
94	            sum += d;
95	            dbl = !dbl;
96	        }
97	        return (10 - (sum % 10)) % 10;
98	    }
99	
100	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
101	        OwnerPageDto ownerPageDto = new OwnerPageDto();
102	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
103	        ownerPageDto.setPage(ownerPage.getNumber());
104	        ownerPageDto.setSize(ownerPage.getSize());
105	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
106	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
107	        return ownerPageDto;
108	    }
109	}
